import math

def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def solve():
    solutions = []
    # Check n=0, 1, 2
    for n in [0, 1, 2]:
        d = 2 * n - 1
        numerator = 3 * (math.factorial(n + 2) + 1)
        if d != 0 and numerator % d == 0:
            solutions.append(n)

    # Check larger n
    # For n > 2, d = 2n-1 must be prime.
    # And ( (d+5)/2 )! \equiv -1 (mod d)
    for d in range(3, 10000):
        if is_prime(d):
            if d == 3:
                # Already checked n=2
                continue
            k = (d + 5) // 2
            fact_k = 1
            for i in range(1, k + 1):
                fact_k = (fact_k * i) % d
            if fact_k == d - 1: # fact_k \equiv -1 (mod d)
                n = (d + 1) // 2
                solutions.append(n)
    return sorted(list(set(solutions)))

print(solve())
